const { URL } = require('url');
const https = require('https');
const log = require('SyntheticsLogger');
const synthetics = require('Synthetics');

/**
 * Canario sintetico (seccion 9.5): heartbeat continuo contra los BFFs a
 * traves de la API real (API Gateway -> CloudFront -> WAF), simulando el
 * mismo criterio de aceptacion manual de punta a punta que cerro la
 * Fase 11 de este proyecto (login -> movimientos -> transferencia), pero
 * corriendo solo, 24/7, en produccion real.
 *
 * Simplificacion documentada: verifica /health de ambos BFFs en vez de
 * ejecutar un login OAuth + transferencia real con credenciales de un
 * usuario de prueba -- eso requeriria distribuir una contrasena de un
 * usuario sintetico dentro del propio canario (superficie de riesgo
 * adicional). El flujo autenticado completo se ejercita en su lugar por
 * las pruebas automatizadas de CI (Fase 13) contra cada entorno antes de
 * cada despliegue (item 14.9), que es donde corresponde la cobertura de
 * negocio -- el canario cubre disponibilidad real del endpoint publico
 * las 24 horas entre despliegues.
 */
const checkEndpoint = async function (path) {
  const baseUrl = process.env.API_BASE_URL;
  const url = new URL(path, baseUrl);

  const requestOptions = { hostname: url.hostname, method: 'GET', path: url.pathname };
  const stepConfig = { includeRequestHeaders: true, includeResponseHeaders: true, restrictedHeaders: [], includeRequestBody: false, includeResponseBody: true };

  await synthetics.executeHttpStep(`check ${path}`, requestOptions, null, stepConfig);
};

exports.handler = async () => {
  await checkEndpoint('/web/health');
  await checkEndpoint('/mobile/health');
};
